Function bisiesto <- EsBisiesto(anio As Integer)
  Define bisiesto As Boolean;
  bisiesto <- (anio Mod 4 = 0 And anio Mod 100 <> 0) Or anio Mod 400 = 0;
EndFunction

Algorithm Principal
  Define anio As Integer;
  Read anio;
  If EsBisiesto(anio) Then
    Write "Es bisiesto";
  Else
    Write "No es bisiesto";
  EndIf
EndAlgorithm
